import Uint64 = require( '@stdlib/number/uint64/ctor' );
import and = require( './index' );


// TESTS //

// The function returns a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	and( a, a ); // $ExpectType Uint64
}

// The compiler throws an error if the function is provided a first argument which is not a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	and( true, a ); // $ExpectError
	and( false, a ); // $ExpectError
	and( null, a ); // $ExpectError
	and( undefined, a ); // $ExpectError
	and( '5', a ); // $ExpectError
	and( [], a ); // $ExpectError
	and( {}, a ); // $ExpectError
	and( ( x: number ): number => x, a ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	and( a, true ); // $ExpectError
	and( a, false ); // $ExpectError
	and( a, null ); // $ExpectError
	and( a, undefined ); // $ExpectError
	and( a, '5' ); // $ExpectError
	and( a, [] ); // $ExpectError
	and( a, {} ); // $ExpectError
	and( a, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const a = new Uint64( 5 );

	and(); // $ExpectError
	and( a ); // $ExpectError
	and( a, a, a ); // $ExpectError
}

// Attached to main export is an `assign` method which returns a collection...
{
	const out = [ 0, 0 ];

	and.assign( 1, 2, 3, 4, out, 1, 0 ); // $ExpectType number[]
}

// The compiler throws an error if the `assign` method is provided invalid arguments...
{
	const out = [ 0, 0 ];

	and.assign( '5', 2, 3, 4, out, 1, 0 ); // $ExpectError
	and.assign( 1, '2', 3, 4, out, 1, 0 ); // $ExpectError
	and.assign( 1, 2, '3', 4, out, 1, 0 ); // $ExpectError
	and.assign( 1, 2, 3, '4', out, 1, 0 ); // $ExpectError
	and.assign( 1, 2, 3, 4, 123, 1, 0 ); // $ExpectError
	and.assign( 1, 2, 3, 4, out, '1', 0 ); // $ExpectError
	and.assign( 1, 2, 3, 4, out, 1, '0' ); // $ExpectError
}

// Attached to main export is a `strided` method which returns a collection...
{
	const a = [ 1, 2 ];
	const b = [ 3, 4 ];
	const out = [ 0, 0 ];

	and.strided( a, 1, 0, b, 1, 0, out, 1, 0 ); // $ExpectType number[]
}

// The compiler throws an error if the `strided` method is provided invalid arguments...
{
	const a = [ 1, 2 ];
	const b = [ 3, 4 ];
	const out = [ 0, 0 ];

	and.strided( 123, 1, 0, b, 1, 0, out, 1, 0 ); // $ExpectError
	and.strided( a, '1', 0, b, 1, 0, out, 1, 0 ); // $ExpectError
	and.strided( a, 1, '0', b, 1, 0, out, 1, 0 ); // $ExpectError
	and.strided( a, 1, 0, 123, 1, 0, out, 1, 0 ); // $ExpectError
	and.strided( a, 1, 0, b, '1', 0, out, 1, 0 ); // $ExpectError
	and.strided( a, 1, 0, b, 1, '0', out, 1, 0 ); // $ExpectError
	and.strided( a, 1, 0, b, 1, 0, 123, 1, 0 ); // $ExpectError
	and.strided( a, 1, 0, b, 1, 0, out, '1', 0 ); // $ExpectError
	and.strided( a, 1, 0, b, 1, 0, out, 1, '0' ); // $ExpectError
}
